// Single runnable file with multiple top-level package-private classes.
package com.bank.record;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import java.util.logging.*;

public class ImmutableDemo {
    private static final Logger log = Logger.getLogger(ImmutableDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<String> refs = new ArrayList<>(List.of("UTR-1001", "UTR-1002"));
        TransferRecord record = new TransferRecord(
                "SAV2001", "CUR3001", new BigDecimal("50000"),
                LocalDateTime.of(2026, 10, 26, 10, 15), refs);

        log.info(() -> "Created immutable record: " + record);

        // Attempt 1: mutate the list we passed IN — record must be unaffected.
        refs.add("UTR-HACK");
        log.info(() -> "After mutating the source list, record refs: " + record.getReferenceIds());

        // Attempt 2: mutate the list we got OUT — must throw or not affect record.
        try {
            record.getReferenceIds().add("UTR-HACK2");
        } catch (UnsupportedOperationException ex) {
            log.warning("Returned list is unmodifiable — mutation blocked (good).");
        }
        log.info(() -> "Record refs still: " + record.getReferenceIds());

        // "Change" = a NEW object, original untouched.
        TransferRecord repriced = record.withAmount(new BigDecimal("60000"));
        log.info(() -> "Original amount Rs." + record.getAmount()
                + ", new object amount Rs." + repriced.getAmount());
    }
}

